    fl=set(x["flavor"] for x in o["other_side"])
    print("%-58s %-26s h=%s(%s) others=%d %s" % (o["file"][:58], o["lock"][:26], o["handler_side"][0]["handler"][:24], o["handler_side"][0]["flavor"], len(o["other_side"]), sorted(fl)))

